def transform(grid):
    """Move the non-background figure next to the vertical 2-bar and mark its far side."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The full-height color-2 separator divides the canvas into two work areas.
    divider_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if not divider_cols:
        return out
    divider = divider_cols[0]

    counts = Counter(v for row in grid for v in row if v != 2)
    background = counts.most_common(1)[0][0]
    figure_cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                    if grid[r][c] not in (background, 2)]
    if not figure_cells:
        return out
    min_c = min(c for _, c, _ in figure_cells)
    max_c = max(c for _, c, _ in figure_cells)

    if max_c < divider:  # figure is left of the bar: slide it right
        shift = divider - 1 - max_c
        far_edge = min_c + shift
        marker_col = far_edge - 1
    elif min_c > divider:  # figure is right of the bar: slide it left
        shift = divider + 1 - min_c
        far_edge = max_c + shift
        marker_col = far_edge + 1
    else:
        return out

    out = [[background if v not in (2,) else v for v in row] for row in grid]
    for r, c, value in figure_cells:
        nc = c + shift
        if 0 <= nc < w:
            out[r][nc] = value
    if 0 <= marker_col < w:
        for r in range(h):
            out[r][marker_col] = 8
    return out


